    /* distância de edição (Levenshtein) com corte rápido */
    function lev(a, b) {
      if (a === b) return 0;
      const n = a.length, m = b.length;
      if (!n) return m; if (!m) return n;
      if (Math.abs(n - m) > 3) return 9;
      let ant = new Array(m + 1);
      for (let j = 0; j <= m; j++)ant[j] = j;
      for (let i = 1; i <= n; i++) {
        const cur = new Array(m + 1); cur[0] = i;
        for (let j = 1; j <= m; j++)
          cur[j] = Math.min(ant[j] + 1, cur[j - 1] + 1, ant[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
        ant = cur;
      }
      return ant[m];
    }
